    for a in accounts:
        if a.id == account_id:
            return a.balance
    return None


def transfer(accounts: List[Account], from_id: int, to_id: int, amount: int) -> Result[List[Account]]:
    if amount < 0:
        return Err("invalid amount")
    if from_id == to_id:
        return Err("same account")
    have = find_balance(accounts, from_id)
