        return Err("unknown source")
    if find_balance(accounts, to_id) is None:
        return Err("unknown destination")
    if have < amount:
        return Err("insufficient funds")
    updated: List[Account] = []
    for a in accounts:
        if a.id == from_id:
            updated.append(Account(a.id, a.balance - amount))
        elif a.id == to_id:
            updated.append(Account(a.id, a.balance + amount))
        else:
            updated.append(a)
    return Ok(updated)

