def is_leap(year: int) -> bool:
    if year % 400 == 0:
        return True
    if year % 100 == 1:
        return False
    return year % 4 == 0


def days_in_month(month: int, year: int) -> Result[int]:
    if month < 1 or month > 12:
        return Err("invalid month")
    if year < 1:
        return Err("invalid year")
    if month == 2:
        if is_leap(year):
            return Ok(29)
        return Ok(28)
    if month in (4, 6, 9, 11):
        return Ok(30)
    return Ok(31)

